mapper.update:
/*updateSellerMCSCNoticeLCount - ICOMBOARD_NOTICE 조회수 증가*/

		UPDATE ICOMBOARD_NOTICE
		SET LCOUNT = NVL(LCOUNT, 0) + 1
		WHERE BID = #{BID}
		  AND BTYPE = #{BTYPE}

mapper.insert:
/*insertNoticeReadLog - 공지사항 읽음 기록 등록*/

		INSERT INTO ICOMBOARD_NOTICE_READ (BID, BTYPE, COM_CODE, USER_ID, READ_DATE)
		VALUES (#{bid}, #{btype}, #{comCode}, #{userId}, TO_CHAR(SYSDATE, 'YYYYMMDD'))

mapper.select:
/*selectNoticeReadCount - 공지사항 읽음 여부 체크*/

		SELECT COUNT(*) FROM ICOMBOARD_NOTICE_READ
		WHERE BID = #{bid} AND BTYPE = #{btype}
		  AND COM_CODE = #{comCode} AND USER_ID = #{userId}

/*selectInquiryList*/
SELECT Q.QID, Q.SUBJECT, Q.QTYPE, C.TEXT1 AS QTYPE_NAME, Q.STATUS, CASE Q.STATUS WHEN 'C' THEN '답변대기' WHEN 'A' THEN '답변완료' WHEN 'X' THEN '취소' END AS STATUS_NAME, Q.REG_USER_NAME, TO_CHAR(TO_DATE(Q.REG_DATE, 'YYYYMMDD'), 'YYYY.MM.DD') AS REG_DATE_DIS, Q.REG_DATE, Q.REG_TIME, CASE WHEN Q.IMAGE_KEY IS NOT NULL THEN 'Y' ELSE 'N' END AS HAS_ATTACH, Q.LCOUNT, (SELECT COUNT(*) FROM KEP.ICOMQAA WHERE QID = Q.QID) AS ANSWER_CNT FROM KEP.ICOMQA Q LEFT JOIN ICOMCOD1 C ON C.TYPE = 'QTYPE' AND C.CODE = Q.QTYPE WHERE Q.COMPANY = #{st_company} AND Q.STATUS <> 'X'
AND Q.REG_DATE >= #{st_from_date}
AND Q.REG_DATE <= #{st_to_date}
AND Q.QTYPE = #{st_qtype}
AND Q.STATUS = #{st_status}
ORDER BY Q.REG_DATE DESC, Q.REG_TIME DESC

/*selectInquiryDetail*/
SELECT 'Q' AS ROW_TYPE, Q.QID AS ID, Q.SUBJECT, DBMS_LOB.SUBSTR(Q.CONTEXT, 4000, 1) AS CONTEXT, Q.IMAGE_KEY, Q.REG_USER_NAME, TO_CHAR(TO_DATE(Q.REG_DATE, 'YYYYMMDD'), 'YYYY.MM.DD') AS REG_DATE_DIS, Q.REG_DATE, Q.REG_TIME, Q.QTYPE, C.TEXT1 AS QTYPE_NAME, Q.STATUS, CASE Q.STATUS WHEN 'C' THEN '답변대기' WHEN 'A' THEN '답변완료' WHEN 'X' THEN '취소' END AS STATUS_NAME, Q.LCOUNT FROM KEP.ICOMQA Q LEFT JOIN ICOMCOD1 C ON C.TYPE = 'QTYPE' AND C.CODE = Q.QTYPE WHERE Q.QID = #{st_qid} AND Q.COMPANY = #{st_company}
UNION ALL
SELECT 'A' AS ROW_TYPE, A.AID AS ID, NULL AS SUBJECT, DBMS_LOB.SUBSTR(A.CONTEXT, 4000, 1) AS CONTEXT, A.IMAGE_KEY, A.REG_USER_NAME, TO_CHAR(TO_DATE(A.REG_DATE, 'YYYYMMDD'), 'YYYY.MM.DD') AS REG_DATE_DIS, A.REG_DATE, A.REG_TIME, NULL AS QTYPE, NULL AS QTYPE_NAME, NULL AS STATUS, NULL AS STATUS_NAME, NULL AS LCOUNT FROM KEP.ICOMQAA A WHERE A.QID = #{st_qid} ORDER BY ROW_TYPE, ID

mapper.update:
/*updateInquiryViewCount*/

		UPDATE KEP.ICOMQA
		SET LCOUNT = NVL(LCOUNT, 0) + 1
		WHERE QID = #{st_qid}

/*cancelInquiry*/

		UPDATE KEP.ICOMQA
		SET STATUS = 'X',
		    CANCEL_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD'),
		    CANCEL_TIME = TO_CHAR(SYSDATE, 'HH24MISS')
		WHERE QID = #{st_qid, jdbcType=NUMERIC}
		  AND COMPANY = #{st_company, jdbcType=VARCHAR}
		  AND STATUS = 'C'
